import{_ as l,o as t,c as a,a4 as i}from"./chunks/framework.DzJZdBQK.js";const h=JSON.parse('{"title":"写作课作业-099","description":"","frontmatter":{"date":"2020-10-27T08:24:09","title":"写作课作业-099","categories":["写作","作业","一年顶十年"],"tags":["写作","作业","一年顶十年"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/096.md","filePath":"posts/homework/096.md"}'),o={name:"posts/homework/096.md"};function p(r,e,s,n,_,c){return t(),a("div",null,[...e[0]||(e[0]=[i('<blockquote><p>10.26《一年定十年》之《打基础 时间 如何让你的时间投资卓有成效？》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ol><li>从今天开始，你不仅要理财，更要理时间。</li><li>给自己的时间定价——毕竟没什么门槛的交往，效率往往不高，很难产生价值。</li><li>学会拒绝（强势），可以节省大量时间。</li><li>利用高效时间创造极大的价值。</li><li>怎样才能做到少混日子、多产出呢？有一点非常重要，那就是加大你的反省密度。</li><li>如何拥有更多的时间，最有效的办法是付费请人帮自己做事。</li><li>事实上，除了少数必须要花很多时间才能做好的事情外，对于一般的事情，真没必要给自己留太多时间，完全可以把截止时间提前，甚至大大提前。</li><li>回顾并分析当日的时间花费情况，看看哪些事合理花费，哪些是不合理花费。</li></ol><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>时常听到，你不理财，财不理你。但对于时间，常常是让它如流水般流逝。</p><p>让自己重视时间的一个方法就是就是给自己的时间定价。</p><p>找到自己的高效时间，利用时间评估和反省的方式，提供自己的时间效率。</p><p>通过付费购买他人的时间，来让自己拥有更多的时间。</p><p>时间价值=时间价格*时间效率*可用时长</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',16)])])}const m=l(o,[["render",p]]);export{h as __pageData,m as default};
